const EventEmitter = require('events');

class CircuitBreaker extends EventEmitter {
  constructor(options = {}) {
    super();
    this.failureThreshold = options.failureThreshold || 5;
    this.resetTimeout = options.resetTimeout || 30000;
    this.failureCount = 0;
    this.state = 'CLOSED';
    this.lastFailureTime = null;
    this.pendingRequests = new Map();
    this.requestId = 0;
  }

  isOpen() {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.resetTimeout) {
        this.state = 'HALF_OPEN';
        return false;
      }
      return true;
    }
    return false;
  }

  recordSuccess() {
    this.failureCount = 0;
    this.state = 'CLOSED';
  }

  recordFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
      this.emit('open');
    }
  }
}

class ConnectionPool {
  constructor(size = 10) {
    this.connections = [];
    this.size = size;
    this.available = [];
    this._initPool();
  }

  _initPool() {
    for (let i = 0; i < this.size; i++) {
      const conn = this._createConnection(i);
      this.connections.push(conn);
      this.available.push(conn);
    }
  }

  _createConnection(id) {
    return {
      id,
      active: true,
      queryBuffer: Buffer.alloc(4096),
      resultCache: new Map(),
      metadata: { createdAt: Date.now(), queryCount: 0 },
      execute(sql, params) {
        this.metadata.queryCount++;
        return new Promise((resolve) => {
          setTimeout(() => resolve({ rows: [], affectedRows: 0 }), 10);
        });
      },
      destroy() {
        this.active = false;
        this.queryBuffer = null;
        this.resultCache.clear();
        this.resultCache = null;
        this.metadata = null;
      }
    };
  }

  acquire() {
    if (this.available.length > 0) {
      return this.available.pop();
    }
    return null;
  }

  release(conn) {
    if (conn && conn.active) {
      this.available.push(conn);
    }
  }

  destroyConnection(conn) {
    const idx = this.connections.indexOf(conn);
    if (idx !== -1) {
      conn.destroy();
      this.connections.splice(idx, 1);
    }
  }

  replaceConnection(conn) {
    this.destroyConnection(conn);
    const newConn = this._createConnection(this.connections.length);
    this.connections.push(newConn);
    this.available.push(newConn);
    return newConn;
  }
}

class DatabaseDriver {
  constructor(config = {}) {
    this.pool = new ConnectionPool(config.poolSize || 5);
    this.breaker = new CircuitBreaker(config.circuitBreaker);
    this.retryQueue = [];
    this._setupCircuitBreakerHandlers();
  }

  _setupCircuitBreakerHandlers() {
    this.breaker.on('open', () => {
      this._drainAndReplaceConnections();
    });
  }

  _drainAndReplaceConnections() {
    const connectionsToReplace = [...this.pool.connections];
    connectionsToReplace.forEach(conn => {
      this.pool.replaceConnection(conn);
    });
  }

  async query(sql, params = []) {
    if (this.breaker.isOpen()) {
      throw new Error('Circuit breaker is open');
    }

    const conn = this.pool.acquire();
    if (!conn) {
      throw new Error('No available connections');
    }

    const requestContext = {
      connection: conn,
      sql,
      params,
      startTime: Date.now()
    };

    try {
      const result = await this._executeWithTimeout(requestContext, 5000);
      this.breaker.recordSuccess();
      this.pool.release(conn);
      return result;
    } catch (err) {
      this.breaker.recordFailure();
      this._scheduleRetry(requestContext);
      throw err;
    }
  }

  async _executeWithTimeout(context, timeout) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error('Query timeout'));
      }, timeout);

      context.connection.execute(context.sql, context.params)
        .then(result => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch(err => {
          clearTimeout(timer);
          reject(err);
        });
    });
  }

  _scheduleRetry(context) {
    this.retryQueue.push(context);
    setTimeout(() => this._processRetryQueue(), 1000);
  }

  async _processRetryQueue() {
    const pending = this.retryQueue.splice(0, this.retryQueue.length);
    for (const context of pending) {
      if (!this.breaker.isOpen() && context.connection.active) {
        try {
          const conn = this.pool.acquire();
          if (conn) {
            const result = await conn.execute(context.sql, context.params);
            this.breaker.recordSuccess();
            this.pool.release(conn);
          }
        } catch (e) {
          this.breaker.recordFailure();
        }
      }
    }
  }
}

module.exports = { DatabaseDriver, CircuitBreaker, ConnectionPool };
